BEGIN;
CREATE OR REPLACE FUNCTION encova_finance_report_ledger(account_id UUID,date_from DATE,date_to DATE,requested_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE account public."FinanceAccount"%ROWTYPE;opening NUMERIC;period_debit NUMERIC;period_credit NUMERIC;total INTEGER;page INTEGER;pages INTEGER;items JSONB;BEGIN
 SELECT * INTO account FROM public."FinanceAccount" WHERE id=account_id AND "isPosting" AND currency='PKR';IF account.id IS NULL THEN RAISE EXCEPTION 'FINANCE_ACCOUNT_UNAVAILABLE' USING ERRCODE='P0001';END IF;
 SELECT coalesce(sum(l.debit-l.credit) FILTER(WHERE e."postingDate"<date_from),0),coalesce(sum(l.debit) FILTER(WHERE e."postingDate">=date_from),0),coalesce(sum(l.credit) FILTER(WHERE e."postingDate">=date_from),0),count(*) FILTER(WHERE e."postingDate">=date_from) INTO opening,period_debit,period_credit,total FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE l."accountId"=account.id AND e."postingDate"<=date_to;
 pages:=greatest(1,ceil(total/25.0)::integer);page:=least(requested_page,pages);
 WITH movements AS(SELECT l.id,l.sequence,e.id AS "journalId",e."postingDate",e.reference,e."sourceType",e."sourceId",e."sourceAction",e."reversalOfId",coalesce(m.kind,c.kind,s.kind,am.kind,e."sourceAction") AS "sourceKind",(e."reversalOfId" IS NOT NULL OR m."reversalOfId" IS NOT NULL OR c."reversalOfId" IS NOT NULL OR s."reversalOfId" IS NOT NULL OR am."reversalOfId" IS NOT NULL) AS "isReversal",coalesce(m."reversalOfId",c."reversalOfId",s."reversalOfId",am."reversalOfId",original."sourceId") AS "originalSourceId",CASE WHEN e."reversalOfId" IS NOT NULL THEN original."sourceType" WHEN coalesce(m."reversalOfId",c."reversalOfId",s."reversalOfId",am."reversalOfId") IS NOT NULL THEN e."sourceType" END AS "originalSourceType",l.description,l.debit::text AS debit,l.credit::text AS credit,l."projectId",p.name AS "projectName",l."partyId",party.name AS "partyName",round(opening+sum(l.debit-l.credit) OVER(ORDER BY e."postingDate",e.id,l.sequence,l.id ROWS UNBOUNDED PRECEDING),2)::text AS "runningBalance" FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" LEFT JOIN public."FinanceMovement" m ON m.id=e."movementId" LEFT JOIN public."FinanceCustomerDocument" c ON c.id=e."customerDocumentId" LEFT JOIN public."FinanceSupplierDocument" s ON s.id=e."supplierDocumentId" LEFT JOIN public."FinanceAssetMovement" am ON am.id=e."assetMovementId" LEFT JOIN public."FinanceJournalEntry" original ON original.id=e."reversalOfId" LEFT JOIN public."Project" p ON p.id=l."projectId" LEFT JOIN public."FinanceParty" party ON party.id=l."partyId" WHERE l."accountId"=account.id AND e."postingDate" BETWEEN date_from AND date_to),bounded AS(SELECT * FROM movements ORDER BY "postingDate","journalId",sequence,id LIMIT 25 OFFSET(page-1)*25)
 SELECT coalesce(jsonb_agg(to_jsonb(bounded) ORDER BY "postingDate","journalId",sequence,id),'[]'::jsonb) INTO items FROM bounded;
 RETURN jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,date_to,jsonb_build_object('report','GENERAL_LEDGER','accountId',account.id)),'account',jsonb_build_object('id',account.id,'code',account.code,'name',account.name,'type',account.type,'normalSide',account."normalSide",'controlType',account."controlType",'active',account.active),'openingBalance',round(opening,2)::text,'periodDebit',round(period_debit,2)::text,'periodCredit',round(period_credit,2)::text,'closingBalance',round(opening+period_debit-period_credit,2)::text,'items',items,'total',total,'page',page,'pages',pages);
END $$;
COMMIT;
